  await cast();const enemy=donor(b,{kws:positive?['flanking']:['flanking','flying']});enemy.attacking=a;await g.emit('attacks',{card:enemy,player:b,defender:a});await settle(g);assert.equal(enemy.kw('flanking'),false);assert.equal(enemy.damage,positive?1:0);
