  const c=donor(),s=await cast(name,{aim:name==="Kaya's Ghostform"?[c]:[]});if(name==='Angelic Renewal')await g.destroy(c);else await g.move(c,positive?'graveyard':'exile');await settle(g);assert.equal(c.zone,name==='Angelic Renewal'&&!positive?'graveyard':'battlefield');assert.equal(s.zone,name==='Angelic Renewal'&&!positive?'battlefield':'graveyard');
